package com.hiresense.service;
import com.fasterxml.jackson.core.type.TypeReference; import com.fasterxml.jackson.databind.ObjectMapper; import com.hiresense.domain.*; import com.hiresense.domain.enums.*; import com.hiresense.dto.MatchDtos.MatchResponse; import com.hiresense.exception.ApiException; import com.hiresense.repository.*; import org.apache.pdfbox.pdmodel.*; import org.apache.pdfbox.pdmodel.common.PDRectangle; import org.apache.pdfbox.pdmodel.font.PDType1Font; import org.apache.pdfbox.pdmodel.font.Standard14Fonts; import org.apache.pdfbox.pdmodel.PDPageContentStream; import org.springframework.data.domain.*; import org.springframework.http.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.io.*; import java.math.*; import java.util.*; import java.util.stream.*;
@Service public class MatchService {private final ResumeService resumes;private final JobService jobs;private final MatchResultRepository matches;private final CandidateProfileRepository profiles;private final AppUserRepository users;private final ObjectMapper json;private final MlClient ml;
 public MatchService(ResumeService r,JobService j,MatchResultRepository m,CandidateProfileRepository p,AppUserRepository u,ObjectMapper o,MlClient c){resumes=r;jobs=j;matches=m;profiles=p;users=u;json=o;ml=c;}
 @Transactional public MatchResponse scoreForUser(String email,Long resumeId,Long jobId){AppUser user=users.findByEmailIgnoreCase(email).orElseThrow(()->ApiException.notFound("User not found"));boolean privileged=user.getRoles().stream().map(Role::getName).anyMatch(r->r==RoleName.HR||r==RoleName.ADMIN);Resume resume=resumes.get(resumeId);if(!privileged){Long own=profiles.findByUserId(user.getId()).orElseThrow(()->ApiException.notFound("Candidate profile not found")).getId();if(!resume.getCandidateProfile().getId().equals(own))throw ApiException.forbidden("Not authorized to score this resume");}return score(resumeId,jobId);}
 @Transactional public MatchResponse score(Long resumeId,Long jobId){Resume r=resumes.get(resumeId);ParsedResumeData d=resumes.data(resumeId);Job job=jobs.get(jobId);List<String> rs=read(d.getSkillsJson());List<String> required=job.getSkills().stream().filter(x->x.getSkillType()==JobSkillType.REQUIRED).map(x->x.getSkill().getName()).toList();List<String> preferred=job.getSkills().stream().filter(x->x.getSkillType()==JobSkillType.PREFERRED).map(x->x.getSkill().getName()).toList();Map<String,Object> request=new LinkedHashMap<>();request.put("resume_text",safeText(d));request.put("job_text",job.getTitle()+"\n"+job.getDescription());request.put("resume_skills",rs);request.put("required_skills",required);request.put("preferred_skills",preferred);request.put("candidate_experience_years",d.getYearsExperience());request.put("required_experience_years",job.getMinExperienceYears());request.put("candidate_education",d.getEducationJson());request.put("required_education",job.getEducationLevel());Map<String,Object> out=ml.match(request);Scored x=out.isEmpty()?fallback(rs,required,preferred,d.getYearsExperience(),job.getMinExperienceYears(),d.getEducationJson(),job.getEducationLevel()):fromMl(out,rs,required,preferred);if(x.overall==null)x=fallback(rs,required,preferred,d.getYearsExperience(),job.getMinExperienceYears(),d.getEducationJson(),job.getEducationLevel());
  MatchResult m=new MatchResult();m.setResume(r);m.setJob(job);m.setOverallScore(x.overall);m.setSemanticScore(x.semantic);m.setSkillScore(x.skills);m.setExperienceScore(x.experience);m.setEducationScore(x.education);m.setMatchedSkillsJson(write(x.matched));m.setMissingSkillsJson(write(x.missing));m.setFeedbackJson(write(x.feedback));m.setImprovementTipsJson(write(x.tips));return map(matches.save(m));}
 @Transactional(readOnly=true) public Page<MatchResponse> ranked(Long jobId,int page,int size){return matches.findAllByJobIdOrderByOverallScoreDesc(jobId,PageRequest.of(Math.max(0,page),Math.min(100,Math.max(1,size)))).map(this::map);}
 @Transactional public List<MatchResponse> recommendations(String email,int size){Long userId=users.findByEmailIgnoreCase(email).orElseThrow(()->ApiException.notFound("User not found")).getId();Long profileId=profiles.findByUserId(userId).orElseThrow(()->ApiException.notFound("Candidate profile not found")).getId();return recommendationsForProfile(profileId,size);}
 @Transactional public List<MatchResponse> recommendationsForProfile(Long profileId,int size){List<Resume> rr=resumes.listEntities(profileId);if(rr.isEmpty())return List.of();List<MatchResponse> out=new ArrayList<>();for(var j:jobs.list(0,1000,true).getContent())out.add(score(rr.get(0).getId(),j.id()));return out.stream().sorted(Comparator.comparing(MatchResponse::overallScore).reversed()).limit(Math.max(1,Math.min(size,100))).toList();}
 @Transactional(readOnly=true) public byte[] reportForUser(String email,Long id){AppUser user=users.findByEmailIgnoreCase(email).orElseThrow(()->ApiException.notFound("User not found"));MatchResult match=matches.findById(id).orElseThrow(()->ApiException.notFound("Match not found"));boolean privileged=user.getRoles().stream().map(Role::getName).anyMatch(r->r==RoleName.HR||r==RoleName.ADMIN);if(!privileged){Long own=profiles.findByUserId(user.getId()).orElseThrow(()->ApiException.notFound("Candidate profile not found")).getId();if(!match.getResume().getCandidateProfile().getId().equals(own))throw ApiException.forbidden("Not authorized to access this match report");}return report(id);}
 @Transactional(readOnly=true)
 public byte[] report(Long id){MatchResult m=matches.findById(id).orElseThrow(()->ApiException.notFound("Match not found"));try(ByteArrayOutputStream out=new ByteArrayOutputStream();PDDocument d=new PDDocument()){PDPage page=new PDPage(PDRectangle.LETTER);d.addPage(page);try(PDPageContentStream c=new PDPageContentStream(d,page)){c.beginText();c.setFont(new PDType1Font(Standard14Fonts.FontName.HELVETICA_BOLD),18);c.newLineAtOffset(50,740);c.showText("HireSense Match Report");c.setFont(new PDType1Font(Standard14Fonts.FontName.HELVETICA),11);String[] lines={"Job: "+m.getJob().getTitle(),"Resume: "+m.getResume().getOriginalFileName(),"Overall score: "+m.getOverallScore()+" / 100","Semantic: "+m.getSemanticScore()+" | Skills: "+m.getSkillScore(),"Experience: "+m.getExperienceScore()+" | Education: "+m.getEducationScore(),"Matched skills: "+m.getMatchedSkillsJson(),"Missing skills: "+m.getMissingSkillsJson(),"Feedback: "+m.getFeedbackJson(),"Improvement tips: "+m.getImprovementTipsJson()};float y=700;for(String line:lines){c.newLineAtOffset(0,-28);c.showText(line.length()>115?line.substring(0,115):line);y-=28;}c.endText();}d.save(out);return out.toByteArray();}catch(IOException e){throw new IllegalStateException("Could not create report",e);}}
 private String safeText(ParsedResumeData d){String t=d.getFullText()==null?"":d.getFullText();if(d.getExtractedName()!=null&&!d.getExtractedName().isBlank())t=t.replaceAll("(?i)"+java.util.regex.Pattern.quote(d.getExtractedName())," ");t=t.replaceAll("(?i)\\b(gender|sex|male|female|non[- ]?binary|pronouns?)\\s*[:\\-]?\\s*[^\\n]*"," ");t=t.replaceAll("(?i)\\b(date of birth|dob|age|aged)\\s*[:\\-]?\\s*\\d{1,3}\\b"," ");t=t.replaceAll("(?i)\\b(photo|photograph|headshot|profile picture)\\b"," ");return t;}
 private Scored fromMl(Map<String,Object> o,List<String> rs,List<String> required,List<String> preferred){Map<String,Object> cs=o.get("component_scores") instanceof Map<?,?> m?(Map<String,Object>)m:Map.of();BigDecimal overall=num(o.get("overall_score"),null);BigDecimal sem=num(cs.get("semantic"),overall);BigDecimal skill=num(cs.get("skills"),num(cs.get("skill"),overall));BigDecimal exp=num(cs.get("experience"),overall);BigDecimal edu=num(cs.get("education"),overall);List<String> matched=read(o.get("matched_skills"));List<String> missing=read(o.get("missing_skills"));return new Scored(overall,sem,skill,exp,edu,matched,missing,feedbackMap(o.get("section_feedback")),read(o.get("improvement_tips")));}
 private Scored fallback(List<String> rs,List<String> req,List<String> pref,BigDecimal exp,BigDecimal min,String education,String requiredEdu){Set<String> have=rs.stream().map(x->x.toLowerCase(Locale.ROOT)).collect(Collectors.toSet());List<String> matched=req.stream().filter(x->have.contains(x.toLowerCase(Locale.ROOT))).toList();List<String> missing=req.stream().filter(x->!have.contains(x.toLowerCase(Locale.ROOT))).toList();int denom=Math.max(1,req.size());BigDecimal skill=bd(100.0*matched.size()/denom);BigDecimal preferred=bd(pref.stream().filter(x->have.contains(x.toLowerCase(Locale.ROOT))).count()*100.0/Math.max(1,pref.size()));skill=bd(skill.doubleValue()*.8+preferred.doubleValue()*.2);BigDecimal experience=min==null||min.signum()==0?bd(100):bd(Math.min(100,100*(exp==null?0:exp.doubleValue())/min.doubleValue()));BigDecimal edu=requiredEdu==null||requiredEdu.isBlank()?bd(100):(education!=null&&education.toLowerCase(Locale.ROOT).contains(requiredEdu.toLowerCase(Locale.ROOT))?bd(100):bd(50));BigDecimal overall=bd(skill.doubleValue()*.5+experience.doubleValue()*.3+edu.doubleValue()*.2);return new Scored(overall,overall,skill,experience,edu,matched,missing,Map.of("skills",missing.isEmpty()?"Strong skill alignment":"Address missing required skills"),missing.stream().map(x->"Consider adding evidence for "+x).toList());}
 private MatchResponse map(MatchResult m){return new MatchResponse(m.getId(),m.getResume().getId(),m.getJob().getId(),m.getOverallScore(),m.getSemanticScore(),m.getSkillScore(),m.getExperienceScore(),m.getEducationScore(),read(m.getMatchedSkillsJson()),read(m.getMissingSkillsJson()),asMap(m.getFeedbackJson()),read(m.getImprovementTipsJson()));}
 private BigDecimal bd(double x){return BigDecimal.valueOf(Math.max(0,Math.min(100,x))).setScale(2,RoundingMode.HALF_UP);}private BigDecimal num(Object x,BigDecimal d){try{return x==null?d:bd(Double.parseDouble(String.valueOf(x)));}catch(Exception e){return d;}}
 @SuppressWarnings("unchecked") private List<String> read(Object x){if(x instanceof List<?> l)return l.stream().map(String::valueOf).toList();if(x instanceof String s)try{return json.readValue(s,new TypeReference<List<String>>(){});}catch(Exception e){}return List.of();}private String write(Object x){try{return json.writeValueAsString(x);}catch(Exception e){return "[]";}}@SuppressWarnings("unchecked")private Map<String,Object> asMap(Object x){if(x instanceof Map<?,?> m)return (Map<String,Object>)m;if(x instanceof String s)try{return json.readValue(s,new TypeReference<Map<String,Object>>(){});}catch(Exception ignored){}return Map.of();}private Map<String,Object> feedbackMap(Object x){if(x instanceof Map<?,?>)return asMap(x);if(x instanceof List<?> items){Map<String,Object> out=new LinkedHashMap<>();for(Object item:items){String message=String.valueOf(item);String lower=message.toLowerCase(Locale.ROOT);String section=lower.contains("skill")||lower.contains("resume language")?"Skills":lower.contains("education")?"Education":lower.contains("experience")?"Experience":"Summary";out.putIfAbsent(section,message);}out.putIfAbsent("Certifications","No certification requirement was specified; include relevant credentials where applicable.");return out;}return Map.of();}private record Scored(BigDecimal overall,BigDecimal semantic,BigDecimal skills,BigDecimal experience,BigDecimal education,List<String> matched,List<String> missing,Map<String,Object> feedback,List<String> tips){}
}
